package remframework.geometry.discovery;

import remframework.geometry.discovery.configuration.*;
import remframework.geometry.discovery.experiment.*;
import remframework.geometry.discovery.realization.session.*;
import java.nio.file.*;
import java.util.*;

/** Deterministic machine-readable Stage 2 diagnostic for the normalized 20/30/12 problem. */
public final class N20Stage2DiagnosticMain {
    private N20Stage2DiagnosticMain(){ }
    public static void main(String[] args)throws Exception{Path output=Path.of(args.length>0?args[0]:"target/n20-stage2-diagnostics.csv");int limit=args.length>1?Integer.parseInt(args[1]):10_000,interval=args.length>2?Integer.parseInt(args[2]):100;ConfigurationRequest generationRequest=ConfigurationRequest.byFaceCount(12,3,GeometryEmbeddingDimension.THREE_D,ExperimentProfile.CONVEX_POLYHEDRAL_VOLUME).withFaceComposition(FaceComposition.uniform(5));Configuration configuration=new ConfigurationGenerator().generate(generationRequest,new GenerationExecution(GenerationWorkerCount.auto(),()->false,null)).configurations().getFirst();List<String> lines=new ArrayList<>();lines.add("configuration,seed,iteration,edge_max,edge_rms,planarity_max,planarity_rms,angle_max,angle_rms,dihedral_variance,face_plane_radius_variance,edge_contribution,planarity_contribution,angle_contribution,total_objective,max_velocity,kinetic,stagnation,combinatorial_manifold,boundary_state,self_intersecting,volume,status");for(long seed=42;seed<=46;seed++){TestRequest request=request(configuration,generationRequest,seed,limit);IncrementalSession session=new IncrementalSession(configuration,request);session.resume();for(int i=0;i<limit&&session.result()==null;i++){session.step();if(session.iteration()==1||session.iteration()%interval==0||session.result()!=null){ConstraintObjectiveDiagnostics o=session.objectiveDiagnostics();ThreeDConstraintDiagnostics d=session.threeDConstraintDiagnostics();TestResult result=session.result();String boundary=result==null||result.boundary()==null?"PENDING":result.boundary().status().code().name(),self=result==null||result.boundary()==null?"":Boolean.toString(result.boundary().selfIntersecting()),volume=result!=null&&result.volume()!=null&&result.volume().available()?number(result.volume().absoluteVolume()):"",status=result==null?"RUNNING":result.status().code().name();lines.add(String.join(",",configuration.id().toString(),Long.toString(seed),Integer.toString(session.iteration()),number(o.edgeMaximum()),number(o.edgeRms()),number(o.planarityMaximum()),number(o.planarityRms()),number(o.angleMaximum()),number(o.angleRms()),number(d.dihedralVariance()),number(d.facePlaneRadiusVariance()),number(o.edgeContribution()),number(o.planarityContribution()),number(o.angleContribution()),number(o.totalObjective()),number(o.maximumVelocity()),number(o.kineticMeasure()),session.stagnationStatus().classification().name(),Boolean.toString(d.manifold()),boundary,self,volume,status));}}}Files.createDirectories(output.toAbsolutePath().getParent());Files.write(output,lines);System.out.println(output.toAbsolutePath());}
    private static TestRequest request(Configuration c,ConfigurationRequest generation,long seed,int limit){ThreeDExperimentConditions conditions=new ThreeDExperimentConditions(FacePlanarityMode.REQUIRE_PLANAR_FACES,FaceAngleConditionMode.REQUIRE_EQUAL_ANGLES_WITHIN_EACH_FACE,DihedralConditionMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,FacePlaneRadiusMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,GeometryCenterDefinition.VERTEX_CENTROID,1e-4,1e-3,1e-3);return new TestRequest(c.id(),GeometryEmbeddingDimension.THREE_D,1,seed,1,null,GeometrySymmetryPolicy.MEASURE_ONLY,limit,ExperimentProfile.CONVEX_POLYHEDRAL_VOLUME,null,null,null,1e-3,1e-7,1e-9,1e-6,null,0,0,conditions,BenchmarkPreset.NONE,ThreeDConstraintStrengths.defaults()).withFaceComposition(FaceComposition.uniform(5)).withParameterDerivation(generation);}
    private static String number(double value){return Double.toString(value);}
}
